ga9g(){return"\u0915\u0940\u092e\u0924\u0947\u0902 \u092c\u0926\u0932 \u0938\u0915\u0924\u0940 \u0939\u0948\u0902"},
ga9i(){return"\u0915\u094b\u091f\u0947\u0936\u0928 \u092d\u0947\u091c\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0917\u094d\u0930\u093e\u0939\u0915 \u091a\u0941\u0928\u0947\u0902"},
ga75(){return"RedPet \u0915\u0947 \u0932\u093f\u090f \u092b\u093f\u0930 \u0938\u0947 \u0906\u092e\u0902\u0924\u094d\u0930\u093f\u0924 \u0915\u0930\u0947\u0902"},
